(()=>{
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
const portraits={anand:{name:'Anand Nahar',role:'Co-founder · Chairman & Director',area:'Strategy & brand building',bio:'Anand co-founded Zorko in Surat in 2020. With an engineering background and experience in financial markets, his work spans business strategy, brand building, and expansion.'},amrit:{name:'Amrit Nahar',role:'Co-founder · Whole-time Director',area:'Operations & company direction',bio:'Amrit co-founded Zorko with his brother Anand. His background in environmental engineering and anthropology informs his focus on operations, processes, and the company’s vegetarian food vision.'},neel:{name:'Neel Savani',role:'Chief Operating Officer',area:'Operational leadership',bio:'Neel Savani is Zorko’s Chief Operating Officer. The role connects operational planning with the everyday execution behind the company’s growing network.'},nirmal:{name:'Nirmal Somani',role:'Chief Financial Officer',area:'Financial leadership',bio:'Nirmal Somani serves as Chief Financial Officer, leading the finance function within Zorko’s corporate management team.'},tina:{name:'Tina Jariwala',role:'Company Secretary',area:'Corporate governance',bio:'Tina Jariwala serves as Company Secretary, supporting the company’s corporate governance and secretarial function.'}};
const dialog=document.querySelector('#person-dialog');document.querySelectorAll('[data-person]').forEach(button=>button.addEventListener('click',()=>{const id=button.dataset.person,p=portraits[id];if(!dialog||!p)return;dialog.querySelector('#person-name').textContent=p.name;dialog.querySelector('#person-role').textContent=p.role;dialog.querySelector('#person-bio').textContent=p.bio;dialog.querySelector('#person-area').textContent=p.area;dialog.querySelector('#person-image').src=`assets/official/${id}.webp`;dialog.querySelector('#person-image').alt=p.name;dialog.showModal()}));dialog?.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
const tabs=[...document.querySelectorAll('.benefit-tabs [role="tab"]')];function activate(tab){tabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;document.getElementById(t.getAttribute('aria-controls')).hidden=!selected})}tabs.forEach((t,i)=>{t.tabIndex=i? -1:0;t.addEventListener('click',()=>activate(t));t.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=tabs[(i+1)%tabs.length];if(e.key==='ArrowLeft')next=tabs[(i+tabs.length-1)%tabs.length];if(e.key==='Home')next=tabs[0];if(e.key==='End')next=tabs.at(-1);if(next){e.preventDefault();activate(next);next.focus()}})});
const photos=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('photo-visible');photos.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.photo-reveal').forEach(e=>photos.observe(e));
const nav=document.querySelector('.career-subnav');if(nav){const sections=[...document.querySelectorAll('main section[id]')];const active=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting)nav.querySelectorAll('a').forEach(a=>{if(a.hash==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}),{rootMargin:'-20% 0px -55% 0px'});sections.forEach(s=>active.observe(s))}
document.querySelectorAll('.leader-rail').forEach(rail=>rail.addEventListener('keydown',e=>{if(e.target!==rail)return;if(e.key==='ArrowRight')rail.scrollBy({left:350,behavior:reduce?'instant':'smooth'});if(e.key==='ArrowLeft')rail.scrollBy({left:-350,behavior:reduce?'instant':'smooth'})}));
})();
